package main

import "fmt"

func sum(nums ...int) int {
	total := 0
	for _, n := range nums {
		total += n
	}
	return total
}

func join(sep string, words ...string) string {
	result := ""
	for i, w := range words {
		if i > 0 {
			result += sep
		}
		result += w
	}
	return result
}

func main() {
	fmt.Println("Sum:", sum(1, 2, 3, 4, 5))
	fmt.Println(join(", ", "Go", "Rust", "Zig"))
}

